    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    #[test]
    fn handles_empty_content() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn handles_whitespace_only_lines() {
        let content = "   \n\t\n  \t  ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn mismatched_quotes_not_stripped() {
        let content = "START_DQ=\"value'\nSTART_SQ='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("START_DQ"), Some(&"\"value'".to_string()));
        assert_eq!(vars.get("START_SQ"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn handles_empty_double_quotes() {
        let content = "KEY=\"\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&String::new()));
    }

    #[test]
    fn handles_empty_single_quotes() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&String::new()));
    }

    #[test]
    fn single_double_quote_char_not_stripped() {
        // A lone quote character (len 1) is not stripped
        let content = "KEY=\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn single_single_quote_char_not_stripped() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let content = r#"KEY='hello "world"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"hello \"world\"".to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes() {
        let content = r#"KEY="hello 'world'""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"hello 'world'".to_string()));
    }

    #[test]
    fn backslash_sequences_are_literal() {
        // The parser does not interpret escape sequences like \n or \t
        let content = r"KEY=hello\nworld\t!";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"hello\nworld\t!".to_string()));
    }

    #[test]
    fn escaped_quotes_inside_double_quotes_are_literal() {
        // The parser does not interpret \" as an escape; it strips
        // the outer matching quotes and preserves inner backslashes
        let content = r#"KEY="value with \"escaped\" quotes""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value with \"escaped\" quotes"#.to_string())
        );
    }

    #[test]
    fn escaped_quotes_inside_single_quotes_are_literal() {
        let content = r"KEY='value with \'escaped\' quotes'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r"value with \'escaped\' quotes".to_string())
        );
    }

    #[test]
    fn hash_inside_quoted_value_not_treated_as_comment() {
        let content = r#"KEY="value # not a comment""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn inline_comment_not_stripped() {
        // The parser does not strip inline comments after values
        let content = "KEY=value # this is kept";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is kept".to_string())
        );
    }

    #[test]
    fn leading_trailing_whitespace_on_lines_trimmed() {
        let content = "  KEY=value  ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // The parser does not handle `export` prefix specially
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    #[test]
    fn duplicate_keys_last_value_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn multiple_equals_in_quoted_value() {
        let content = r#"KEY="a=b=c=d""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn spaces_inside_quotes_preserved() {
        // Outer trim happens before unquote, so spaces inside quotes survive
        let content = "KEY=\"  hello  world  \"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  hello  world  ".to_string())
        );
    }

    #[test]
    fn value_starting_with_quote_but_not_ending() {
        let content = "KEY=\"partial";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"partial".to_string()));
    }

    #[test]
    fn value_ending_with_quote_but_not_starting() {
        let content = "KEY=partial\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"partial\"".to_string()));
    }

    #[test]
    fn load_reads_from_file() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "KEY=value\n").unwrap();
        let vars = EnvFileParser::load(&file_path).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::tempdir().unwrap();
        let file_path = dir.path().join(".env");
        std::fs::write(&file_path, "KEY=value\n").unwrap();
        let vars = EnvFileParser::load_optional(&file_path).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }
