    fn single_quotes_inside_double_quotes() {
        let content = r#"KEY="hello 'world'""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"hello 'world'".to_string()));
    }

    #[test]
    fn backslash_sequences_are_literal() {
        // The parser does not interpret escape sequences like \n or \t
        let content = r"KEY=hello\nworld\t!";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"hello\nworld\t!".to_string()));
    }

    #[test]
    fn escaped_quotes_inside_double_quotes_are_literal() {
        // The parser does not interpret \" as an escape; it strips
        // the outer matching quotes and preserves inner backslashes
        let content = r#"KEY="value with \"escaped\" quotes""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value with \"escaped\" quotes"#.to_string())
        );
    }

