        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn inline_comment_not_stripped() {
        // The parser does not strip inline comments after values
        let content = "KEY=value # this is kept";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is kept".to_string())
        );
    }

    #[test]
    fn leading_trailing_whitespace_on_lines_trimmed() {
        let content = "  KEY=value  ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // The parser does not handle `export` prefix specially
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    #[test]
    fn duplicate_keys_last_value_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn multiple_equals_in_quoted_value() {
        let content = r#"KEY="a=b=c=d""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn spaces_inside_quotes_preserved() {
        // Outer trim happens before unquote, so spaces inside quotes survive
        let content = "KEY=\"  hello  world  \"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  hello  world  ".to_string())
        );
    }

    #[test]
    fn value_starting_with_quote_but_not_ending() {
        let content = "KEY=\"partial";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"partial".to_string()));
    }

    #[test]
    fn value_ending_with_quote_but_not_starting() {
        let content = "KEY=partial\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"partial\"".to_string()));
    }

